from datetime import datetime, timedelta, timezone, timedelta

def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds: int, the number of nanoseconds since the Unix epoch
    :param tz: timezone, the timezone of the local time
    :return: datetime or datetime with timezone
    """
    if tz is None:
        return datetime.fromtimestamp(nanoseconds / 1e9, timezone.utc)
    else:
        return datetime.fromtimestamp(nanoseconds / 1e9, tz)

def dehydrate_timedelta(value):
    """ Dehydrator for `timedelta` values.

    :param value:
    :type value: timedelta
    :return:
    """
    if value is None:
        return None
    try:
        delta = value.total_seconds()
        return {"days": int(delta // 86400), "seconds": int(delta % 86400)}
    except AttributeError:
        raise TypeError("value must be a timedelta object")

def dehydrate_time(value):
    """
    Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    if value is None:
        return None
    if not isinstance(value, Time):
        raise ValueError("Input value must be an instance of Time")
    return value.strftime('%H:%M:%S')

def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    if not isinstance(value, Point):
        raise ValueError("Input value must be an instance of Point")

    return {
        "lat": value.lat,
        "lon": value.lon,
        "time": value.time.isoformat()
    }

def keys(self):
    """
    Return the keys of the record.

    :return: list of key names
    """
    return list(self._data.keys())

def index(self, key):
    """
    Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    if key in self._keys:
        return self._keys.index(key)
    else:
        raise KeyError(f"Key not found: {key}")

def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    if not keys:
        return list(self._items.values())

    results = []
    for key in keys:
        if isinstance(key, int):
            if key < len(self._items):
                results.append(list(self._items.values())[key])
        else:
            if key in self._items:
                results.append(self._items[key])

    return results

def data(self, *keys):
    """
    Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    result = {}
    if not keys:
        for key in self._record:
            result[key] = self._record[key]
    else:
        for key in keys:
            if key in self._record:
                result[key] = self._record[key]
            elif isinstance(key, int):
                if key < 0 or key >= len(self._record):
                    raise IndexError("Out-of-bounds index")
                result[list(self._record.keys())[key]] = self._record[list(self._record.keys())[key]]
            else:
                result[key] = None
    return result

def pop_u16(self):
    """
    Remove the last two bytes of data, returning them as a big-endian
    16-bit unsigned integer.
    """
    return self.unpack('>H', 2)

def round_half_to_even(n):
    """
    Round half to even rounding, also known as "bankers' rounding".

    :param n: The number to round.
    :return: The rounded number.
    """
    if n % 1 == 0.5:
        return round(n)
    else:
        return round(n)

