import warnings

import functools

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, category=DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

def parse_version(s: str) -> tuple[int, ...]:
    """
    Poor man's version comparison

    :param s: Version string.
    :return: Tuple of integers representing the version components.
    """
    components = s.split('.')
    try:
        return tuple(map(int, components))
    except ValueError:
        raise ValueError(f"Invalid version format: {s}")

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorator(func):
        if cache is None:
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
        elif lock is None:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        else:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    with lock:
                        return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    with lock:
                        cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        return _update_wrapper(wrapper, func)
    return decorator

from collections import OrderedDict

import time

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    def decorator(func):
        cache = OrderedDict()
        cache_info = [
            0,  # hits
            0,  # misses
            maxsize,
        ]

        def keyargs_hash(args, kwargs):
            if typed:
                return args, tuple(sorted(kwargs.items()))
            return tuple(args), tuple(sorted(kwargs.items()))

        def wrapper(*args, **kwargs):
            k = keyargs_hash(args, kwargs)
            now = timer()
            try:
                exp, value = cache[k]
                if exp >= now:
                    cache.move_to_end(k)
                    cache_info[0] += 1
                    return value
                else:
                    cache.pop(k)
                    cache_info[1] += 1
            except KeyError:
                cache_info[1] += 1

            value = func(*args, **kwargs)
            exp = now + ttl
            while len(cache) >= maxsize:
                cache.popitem(last=False)
            cache[k] = (exp, value)
            cache.move_to_end(k)
            cache_info[0] += 1
            return value

        def cache_clear():
            cache.clear()
            cache_info[0] = 0
            cache_info[1] = 0

        wrapper.cache_clear = cache_clear
        wrapper.cache_info = lambda: {
            'hits': cache_info[0],
            'misses': cache_info[1],
            'maxsize': maxsize,
            'currsize': len(cache),
        }
        return wrapper

    return decorator

from functools import wraps, lru_cache

def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.

    """
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            # Handle the case where lru_cache is not available in Python 2.7
            try:
                func.cache_clear()
            except AttributeError:
                print(
                    "LRU caching is not available in Python 2.7, "
                    "this will have no effect!"
                )
                pass
            return func(*args, **kwargs)
        return wrapper
    return lru_cache(maxsize=maxsize, typed=typed)

from collections import Counter, OrderedDict

from functools import wraps, partial

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    if maxsize <= 0:
        raise ValueError('maxsize must be greater than 0')

    class Node:
        def __init__(self, key, value, freq=1):
            self.key = key
            self.value = value
            self.freq = freq

    def __call__(self, func):
        if hasattr(func, 'cache_info'):
            return func  # already decorated

        cache = OrderedDict()
        frequencies = Counter()
        lfu_nodes = {}

        @wraps(func)
        def wrapper(*args, **kwargs):
            key = (args, tuple(sorted(kwargs.items()))) if typed else args
            if key not in cache:
                result = func(*args, **kwargs)
                cache[key] = Node(key, result)
                frequencies[key] += 1
                node = cache[key]
                if len(cache) > maxsize:
                    lfu_key, lfu_node = cache.popitem(last=False)
                    if lfu_key in frequencies:
                        frequencies[lfu_key] -= 1
                        if frequencies[lfu_key] == 0:
                            del frequencies[lfu_key]
                        if lfu_node.freq == frequencies[lfu_key]:
                            del lfu_nodes[frequencies[lfu_key]]
                if node.freq not in lfu_nodes:
                    lfu_nodes[node.freq] = sortedcache(OrderedDict())
                lfu_nodes[node.freq][key] = node
            else:
                node = cache[key]
                frequencies[key] += 1
                del lfu_nodes[node.freq][key]
                if len(lfu_nodes[node.freq]) == 0:
                    del lfu_nodes[node.freq]
                if node.freq + 1 not in lfu_nodes:
                    lfu_nodes[node.freq + 1] = sortedcache(OrderedDict())
                lfu_nodes[node.freq + 1][key] = Node(key, node.value, node.freq + 1)
            if key in lfu_nodes[node.freq + 1]:
                cache[key] = lfu_nodes[node.freq + 1][key]
            return node.value

        def cache_clear():
            nonlocal cache, frequencies, lfu_nodes
            cache.clear()
            frequencies.clear()
            lfu_nodes.clear()

        def cache_info():
            return (len(cache), maxsize, len(cache) - len(frequencies), 0)

        wrapper.cache_clear = cache_clear
        wrapper.cache_info = cache_info

        return wrapper

    return __call__

def popitem(self):
    """Remove and return the (key, value) pair first inserted."""
    if len(self._data) == 0:
        raise KeyError('dictionary is empty')
    first_key = next(iter(self._data.keys()))
    value = self._data.pop(first_key)
    return (first_key, value)

def get(self, key, default=None):
    """D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None."""
    return self.__getitem__(key, default)

def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    """
    def decorator(method):
        if lock is None:
            def wrapper(self, *args, **kwargs):
                c = cache(self)
                if c is None:
                    return method(self, *args, **kwargs)
                k = key(*args, **kwargs)
                try:
                    return c[k]
                except KeyError:
                    pass  # key not found
                v = method(self, *args, **kwargs)
                try:
                    c[k] = v
                except ValueError:
                    pass  # value too large
                return v
        else:
            def wrapper(self, *args, **kwargs):
                c = cache(self)
                if c is None:
                    return method(self, *args, **kwargs)
                k = key(*args, **kwargs)
                try:
                    with lock(self):
                        return c[k]
                except KeyError:
                    pass  # key not found
                v = method(self, *args, **kwargs)
                try:
                    with lock(self):
                        c[k] = v
                except ValueError:
                    pass  # value too large
                return v
        return _update_wrapper(wrapper, method)
    return decorator

