def directlyProvidedBy(obj):
    """
    Return the interfaces directly provided by the given object

    The value returned is an `~zope.interface.interfaces.IDeclaration`.
    """
    try:
        return zope.interface.interfaces.IDeclaration.subs(obj.__providedBy__)
    except AttributeError:
        return zope.interface.interfaces.IDeclaration.subs(zope.interface.getInterfaces(obj))

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    def cyclic(graph, node, todo, instack, order):
        if node in instack:
            order.append(instack.pop())
        elif node not in todo:
            todo[node] = len(instack)
            for nxt in reversed(graph[node]):
                cyclic(graph, nxt, todo, instack, order)
            instack.append(node)

    def makeGraph(classes):
        graph = {cls: [] for cls in classes}
        for base in classes:
            for cls in classes:
                if cls is not base and issubclass(cls, base):
                    graph[base].append(cls)
        return graph

    graph = makeGraph(classes)
    todo = {}
    instack = []
    order = []

    for cls in classes:
        cyclic(graph, cls, todo, instack, order)

    min_bases = []
    for cls in classes:
        if all(not issubclass(cls, min_cls) for min_cls in min_bases):
            min_bases.append(cls)

    return min_bases

def namesAndDescriptions(self, all=False):
    """Return attribute names and descriptions defined by interface."""

    if not hasattr(self, '__interface__'):
        return {}

    interface = self.__interface__
    attributes = {}

    for name in dir(interface):
        attribute = getattr(interface, name)
        if callable(attribute) and not name.startswith('_'):
            docstring = attribute.__doc__
            description = docstring.strip() if docstring else 'No description available'
            attributes[name] = description

    if not all:
        return {key: value for key, value in attributes.items() if key in self.__dict__}

    return attributes

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    if Broken in getattr(sequence, '__bases__', ()):
        return [sequence]

    cls = sequence.__class__
    if InterfaceClass in cls.__mro__ or zope.interface.declarations.Implements in cls.__mro__:
        output.append(sequence)
    else:
        for v in sequence:
            _normalizeargs(v, output)

    return output

