def reset(self, initial_value=0) -> None:
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    self.context = {}
    for bin in self.bins:
        bin.value = initial_value
    if hasattr(self, 'make_bins'):
        self.bins = self.make_bins()

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    if not seq:
        return False

    if seq.is_source_sequence():
        return False

    if seq.is_fill_request():
        return True

    for item in seq:
        if is_fill_request_seq(item):
            return True

    return False

def is_fill_request_el(obj):
    """
    Object contains executable methods 'fill' and 'request'.

    :param obj: The object to check
    :return: True if the object has 'fill' and 'request' methods, False otherwise
    :rtype: bool
    """
    if not hasattr(obj, 'fill') or not hasattr(obj, 'request'):
        return False
    return callable(obj.fill) and callable(obj.request)

def is_run_el(obj):
    """Object contains executable method 'run'."""
    if callable(getattr(obj, 'run', None)):
        return True
    return False

def is_fill_compute_el(obj):
    """
    Object contains executable methods 'fill' and 'compute'.

    :param obj: The object to check.
    :return: A boolean indicating whether the object has both 'fill' and 'compute' methods.
    """
    try:
        return callable(getattr(obj, 'fill')) and callable(getattr(obj, 'compute'))
    except AttributeError:
        return False

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if level == 0:
        return {}
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        return d1
    result = {}
    for key in d1:
        if key not in d2:
            result[key] = d1[key]
        else:
            diff = difference(d1[key], d2[key], level - 1)
            if diff:
                result[key] = diff
    return result

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    import re
    import exceptionclasses as ec

    key_regex = r"^[a-zA-Z][a-zA-Z0-9_]*$"
    value_regex = r"^[a-zA-Z0-9_.]*$"

    errors = []

    for key, value in labels.items():
        key_error = None
        value_error = None

        if not isinstance(key, str):
            key_error = f"Label key {key} is not of type str"
        elif not re.match(key_regex, key):
            key_error = f"Label key {key} does not match the regex {key_regex}"

        if isinstance(value, list):
            for item in value:
                if not isinstance(item, str):
                    value_error = f"Value '{item}' is not of type str"
                    break
                elif not re.match(value_regex, item):
                    value_error = f"Value '{item}' does not match the regex {value_regex}"
                    break
        elif not isinstance(value, str):
            value_error = f"Value {value} is not of type str"
        elif not re.match(value_regex, value):
            value_error = f"Value {value} does not match the regex {value_regex}"

        if key_error:
            errors.append({str(key): key_error})
        if value_error:
            errors.append({str(value): value_error})

    if errors:
        raise ec.ValidationError(messages=errors)

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    `spec.manifest` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    default_observer_schema = {}
    for resource, manifest in app.spec.manifest.items():
        if 'observer_schema' not in manifest:
            default_observer_schema[resource] = {
                'type': 'object',
                'properties': {
                    'status': {
                        'type': 'object',
                        'properties': {
                            'phase': {
                                'type': 'string'
                            },
                            'conditions': {
                                'type': 'array',
                                'items': {
                                    'type': 'object',
                                    'properties': {
                                        'type': {
                                            'type': 'string'
                                        },
                                        'status': {
                                            'type': 'string'
                                        },
                                        'lastTransitionTime': {
                                            'type': 'string'
                                        }
                                    },
                                    'required': ['type', 'status', 'lastTransitionTime']
                                }
                            }
                        },
                        'required': ['phase', 'conditions']
                    }
                }
            }
    return default_observer_schema

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        # Check if the path exists
        if not os.path.exists(path):
            return False

        # Check if the path is a directory
        if not os.path.isdir(path):
            return False

        # Check for the presence of mandatory files and directories
        mandatory_files = ['manifest.json', 'ocfl.json']
        mandatory_dirs = ['heads', 'objects']

        for file in mandatory_files:
            if file not in os.listdir(path):
                return False

        for dir in mandatory_dirs:
            if dir not in os.listdir(path):
                return False

        # Check the contents of ocfl.json
        ocfl_json_path = os.path.join(path, 'ocfl.json')
        with open(ocfl_json_path, 'r') as f:
            ocfl_json = json.load(f)

        if 'version' not in ocfl_json or ocfl_json['version'] != '1.0':
            return False

        # If all checks pass, return True
        return True

    except Exception as e:
        # Return False if any exception occurs
        return False

def status_str(self, prefix=''):
