def status_str(self, prefix=''):
        """Return string representation of validation log, with optional prefix."""
        if not isinstance(prefix, str):
            raise ValueError("Prefix must be a string")
        return prefix + self.log

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    if extract_spec_version:
        type_value = inventory.get('type')
        if type_value in self.valid_types:
            spec_version = type_value
        else:
            spec_version = self.spec_version
    else:
        spec_version = self.spec_version

    if spec_version == 'v1':
        # Perform validation for specification version 1
        self.validate_v1(inventory)
    elif spec_version == 'v2':
        # Perform validation for specification version 2
        self.validate_v2(inventory)
    else:
        raise SpecificationVersionError(f"Unsupported specification version: {spec_version}")

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""

    missing_digests = []
    unused_digests = set(self.digests)

    for manifest_file in manifest_files:
        file_digests = get_digests_from_manifest(manifest_file)
        unused_digests -= set(file_digests)
        for digest in file_digests:
            if digest not in digests_used:
                missing_digests.append(digest)

    if missing_digests:
        raise ValueError(f"Missing digests: {missing_digests}")

    if unused_digests:
        raise ValueError(f"Unused digests: {unused_digests}")

    return True

def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """

    if not isinstance(prior, InventoryValidator):
        raise TypeError("Input 'prior' must be an instance of InventoryValidator")

    if self.inventory_id != prior.inventory_id:
        raise ValueError("Inventory IDs do not match")

    if len(self.items) != len(prior.items):
        raise ValueError("The number of items does not match")

    for key, item in self.items.items():
        if key not in prior.items:
            raise ValueError(f"Item '{key}' missing in the prior inventory")

        if item.quantity < prior.items[key].quantity:
            raise ValueError(f"Quantity of item '{key}' decreased in the prior inventory")

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """

    logical_path_map = {}

    if version not in inventory:
        raise ValueError(f"Version {version} not found in inventory.")

    for logical_path, file_info in inventory[version].items():
        content_files = set()

        for file_record in file_info:
            content_files.update(file_record['content_files'])

        logical_path_map[logical_path] = content_files

    return logical_path_map

