def render(pieces, style):
    """Render the given version pieces into the requested style."""

    if not pieces:
        raise ValueError("No pieces provided for rendering")

    if not style:
        raise ValueError("No style specified for rendering")

    output = ""
    for piece in pieces:
        if style == "uppercase":
            output += piece.upper()
        elif style == "lowercase":
            output += piece.lower()
        elif style == "titlecase":
            output += piece.title()
        else:
            raise ValueError("Unsupported style: {0}".format(style))

    return output

