def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    import subprocess

    if not all(isinstance(cmd, list) for cmd in commands):
        raise ValueError("All commands must be lists of strings")

    if not all(isinstance(arg, list) for arg in args):
        raise ValueError("All args must be lists of strings")

    for cmd, arg in zip(commands, args):
        full_cmd = cmd + arg

        if verbose:
            print(f"Running command: {' '.join(full_cmd)}")

        try:
            if hide_stderr:
                result = subprocess.check_output(full_cmd, cwd=cwd, env=env, stderr=subprocess.STDOUT)
            else:
                result = subprocess.check_output(full_cmd, cwd=cwd, env=env)

            if result:
                if verbose:
                    print(f"Command output: {result.decode('utf-8').strip()}")

            return result
        except subprocess.CalledProcessError as e:
            error_msg = f"Error running command: {' '.join(cmd)}\n"
            error_msg += f"Return code: {e.returncode}\n"
            error_msg += f"Output: {e.output.decode('utf-8').strip()}"
            raise subprocess.CalledProcessError(e.returncode, cmd, output=e.output, stderr=e.output) from None

