def validate_version_inventories(self, version_dirs):
    """
    Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    root_inventory_path = os.path.join(version_dirs[0], 'inventory')
    if not os.path.exists(root_inventory_path):
        raise ValueError("Root inventory does not exist.")

    root_inventory = load_inventory(root_inventory_path)
    content_digests = {}

    for version_dir in version_dirs:
        inventory_path = os.path.join(version_dir, 'inventory')
        if not os.path.exists(inventory_path):
            raise ValueError(f"Inventory for version {version_dir} does not exist.")

        inventory = load_inventory(inventory_path)
        for item, digest in inventory.items():
            if item not in root_inventory:
                raise ValueError(f"Item {item} from version {version_dir} not found in root inventory.")

            if digest != root_inventory[item]:
                content_digests[item] = (root_inventory[item], digest)

    return content_digests

def find_path_type(path):
    """
    Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    try:
        if not path:
            return "Error: Path is empty"

        if not path.endswith("/"):
            path += "/"

        namaste_file_path = path + "0=*"
        import os
        if os.path.isfile(namaste_file_path):
            with open(namaste_file_path, 'r') as file:
                content = file.read().strip()
                if content == "root":
                    return "root"
                elif content == "object":
                    return "object"
        elif os.path.isdir(path):
            return "object"  # Assuming any non-empty directory contains an object

        return "file"  # Default case, treat as a file
    except Exception as e:
        return str(e)

