    string.

    Args:
        parser (argparse.ArgumentParser): The parser instance.

    Returns:
        str: A space-separated string of the argument flags.
    """
    flags = []
    for action in parser._actions:
        if action.short_opt:
            flags.append(action.short_opt)
        if action.long_opt:
            flags.append(action.long_opt)
    return ' '.join(sorted(set(flags)))

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """

    result = {}
    for d in dicts:
        for key, value in d.items():
            if key in result:
                result[key] += value
            else:
                result[key] = value
    return result

