def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    seen = set()
    queue = set([cls])

    while queue:
        c = queue.pop()
        seen.add(c)

        sc = c.__subclasses__()
        for c in sc:
            if c not in seen:
                queue.add(c)

    return seen

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    base = len(alphabet)
    inverse_alphabet = {char: idx for idx, char in enumerate(alphabet)}
    number = 0

    for char in string:
        if char not in inverse_alphabet:
            raise ValueError(f"Character '{char}' not found in alphabet")
        number = number * base + inverse_alphabet[char]

    return number

def unquote(name):
    """Remove quote from the given name."""
    if isinstance(name, str):
        if name.startswith('"') and name.endswith('"'):
            return name[1:-1]
        if name.startswith("'") and name.endswith("'"):
            return name[1:-1]
    return name

import re

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        import platform as plat
        platform = plat.system() == "Windows"

    if platform:
        # Windows/CMD platform
        return re.findall(r'([^\s"]+|"[^"]*")', s)
    else:
        # POSIX platform
        return [x for x in re.split(r'([^\s"]+|"[^"]*")\s*', s) if x and x != '"']

import datetime

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None or frequency.lower() == "always":
        return None

    frequency_str = frequency.strip()
    if not frequency_str:
        raise ValueError("Invalid frequency string")

    units = {
        "seconds": datetime.timedelta(seconds=1),
        "minutes": datetime.timedelta(minutes=1),
        "hours": datetime.timedelta(hours=1),
        "days": datetime.timedelta(days=1),
        "weeks": datetime.timedelta(weeks=1),
        "months": datetime.timedelta(days=30),
        "years": datetime.timedelta(days=365)
    }

    if " " not in frequency_str:
        raise ValueError("Frequency string must contain a number and a unit")

    number, unit_str = frequency_str.rsplit(" ", 1)
    try:
        number = int(number)
    except ValueError:
        raise ValueError("Invalid number in frequency string")

    unit = unit_str.lower()
    if unit not in units:
        raise ValueError("Invalid unit in frequency string")

    try:
        return number * units[unit]
    except OverflowError:
        raise ValueError("Frequency value too large")

def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    """Given a target config filename and rendered config YAML, write it out to file. Create any
    containing directories as needed. But if the file already exists and overwrite is False,
    abort before writing anything."""

    if not overwrite and os.path.isfile(config_filename):
        raise FileExistsError(f"The file {config_filename} already exists and overwrite is set to False.")

    try:
        config_dir = os.path.dirname(config_filename)
        if config_dir and not os.path.exists(config_dir):
            os.makedirs(config_dir)
        with open(config_filename, 'w', mode=mode) as config_file:
            config_file.write(rendered_config)
    except IOError as e:
        raise IOError(f"Error writing to {config_filename}: {e}") from e

def get_pattern(pattern, strip=True):
