def load_configurations(config_filenames: List[str], overrides: Dict[str, Any] = None, resolve_env: bool = True) -> (Dict[str, Any], List[ParseErrorRecord]):
    """Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors."""

    config_dict = {}
    parse_error_records = []

    for filename in config_filenames:
        try:
            with open(filename, 'r') as fd:
                raw_config = fd.read()

                if resolve_env:
                    raw_config = os.path.expandvars(raw_config)

                if filename.endswith('.yaml'):
                    config = yaml.safe_load(raw_config)
                elif filename.endswith('.json'):
                    config = json.loads(raw_config)
                elif filename.endswith('.toml'):
                    config = toml.loads(raw_config)
                else:
                    raise ValueError(f"Unsupported configuration file format: {filename}")

                if overrides:
                    config.update(overrides)

                config_dict[filename] = config
        except Exception as e:
            parse_error_records.append(ParseErrorRecord(filename, [str(e)]))

    return config_dict, parse_error_records

def _get_seq_with_type(seq, bufsize=None):
