def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    if explicit_mc:
        return explicit_mc

    for base in bases:
        if hasattr(base, '__metaclass__'):
            return base.__metaclass__

    if not bases:
        if '__metaclass__' in globals():
            return globals()['__metaclass__']

    return type

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    if not hasattr(self, '_cache') or not self._cache:
        raise KeyError('cache is empty')

    # Find the item with the least frequency
    least_used = min(self._cache, key=self._cache.get)
    value = self._cache[least_used]
    del self._cache[least_used]
    return (least_used, value)

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    if not self._d:
        raise KeyError('dictionary is empty')
    key, value = self._d.popitem()
    return (key, value)

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    if len(self) == 0:
        raise KeyError('dictionary is empty')
    key = next(reversed(self))
    value = self[key]
    del self[key]
    return (key, value)

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # Check for private message
    try:
        data = json.loads(decode_if_bytes(request.body))
        if "encrypted_magic_envelope" in data:
            return True
    except Exception:
        pass
    # Check for public message
    try:
        xml = etree.fromstring(encode_if_text(request.body))
        if xml.tag == MAGIC_ENV_TAG:
            return True
    except Exception:
        pass
    # Check for legacy payload
    try:
        data = protocol.deserialize(request.body)
        if data.get("legacy"):
            return True
    except Exception:
        pass
    return False

