def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        host = handle.split("@")[1]
    except (AttributeError, IndexError):
        logger.warning("try_retrieve_webfinger_document: invalid handle given: %s", handle)
        return None
    try:
        document, code, exception = fetch_document(
            host=host, path="/.well-known/webfinger?resource=acct:%s" % quote(handle),
        )
        if document:
            return document
    except (SSLError, HTTPException, URLError) as e:
        logger.warning("try_retrieve_webfinger_document: error fetching webfinger document: %s", e)
    hostmeta = retrieve_diaspora_host_meta(host)
    if not hostmeta:
        return None
    url = hostmeta.find_link(rels="lrdd").template.replace("{uri}", quote(handle))
    try:
        document, code, exception = fetch_document(url)
        if exception:
            return None
        return document
    except (SSLError, HTTPException, URLError) as e:
        logger.warning("try_retrieve_webfinger_document: error fetching webfinger document: %s", e)
    return None

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    try:
        host = handle.split("@")[1]
    except AttributeError:
        logger.warning("retrieve_and_parse_diaspora_webfinger: invalid handle given: %s", handle)
        return None
    document, code, exception = fetch_document(
        host=host, path="/.well-known/webfinger?resource=acct:%s" % quote(handle),
    )
    if document:
        return parse_diaspora_webfinger(document)
    hostmeta = retrieve_diaspora_host_meta(host)
    if not hostmeta:
        return None
    url = hostmeta.find_link(rels="lrdd").template.replace("{uri}", quote(handle))
    document, code, exception = fetch_document(url)
    if exception:
        return None
    return parse_diaspora_webfinger(document)

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    logger.debug("send_document: url=%s, data=%s, timeout=%s, method=%s", url, data, timeout, method)
    headers = CaseInsensitiveDict({
        'User-Agent': USER_AGENT,
    })
    if "headers" in kwargs:
        # Update from kwargs
        headers.update(kwargs.get("headers"))
    kwargs.update({
        "data": data, "timeout": timeout, "headers": headers
    })
    try:
        if method.lower() == "post":
            response = requests.post(url, *args, **kwargs)
        elif method.lower() == "get":
            response = requests.get(url, *args, **kwargs)
        else:
            raise ValueError("Unsupported method: {}".format(method))
        logger.debug("send_document: response status code %s", response.status_code)
        return response.status_code, None
    except RequestException as ex:
        logger.debug("send_document: exception %s", ex)
        return None, ex

def dict_insert(dic, val, key, *keys):
    """insert a value of a nested key into a dictionary

    to insert value for a nested key, all ancestor keys should be given as
    method's arguments

    example:
      dict_insert({}, 'val', 'key1.key2'.split('.'))

    :param dic: a dictionary object to insert the nested key value into
    :param val: a value to insert to the given dictionary
    :param key: first key in a chain of key that will store the value
    :param keys: sub keys in the keys chain
    """
    if not isinstance(dic, dict):
        raise ValueError("dic must be a dictionary")
    if not all(isinstance(k, str) for k in keys):
        raise ValueError("all keys must be strings")

    current_dict = dic
    for k in keys[:-1]:
        if k in current_dict and isinstance(current_dict[k], dict):
            current_dict = current_dict[k]
        else:
            current_dict[k] = {}
            current_dict = current_dict[k]
    current_dict[keys[-1]] = val

def list_of_file_names(settings_dirs, spec_option):
    """Return a list of file names from the given settings directories based on the specified option."""
    try:
        if not settings_dirs:
            return []

        if not isinstance(spec_option, str) or spec_option not in ['files', 'directories']:
            raise ValueError("Invalid spec_option. Must be 'files' or 'directories'.")

        file_names = []

        for directory in settings_dirs:
            if os.path.isdir(directory):
                if spec_option == 'files':
                    file_names.extend(os.listdir(directory))
                elif spec_option == 'directories':
                    file_names.extend([d for d in os.listdir(directory) if os.path.isdir(os.path.join(directory, d))])

        return sorted(file_names)
    except (OSError, TypeError) as e:
        print(f"An error occurred: {e}")
        return []

