class IRValidatorException(Exception):
    pass

class SpecValidator:
    @classmethod
    def validate_from_content(cls, spec_content=None):
        """validates that spec (YAML) content has all required fields

        :param spec_content: content of spec file
        :raise IRValidatorException: when mandatory data
        is missing in spec file
        :return: Dictionary with data loaded from a spec (YAML) file
        """
        if spec_content is None:
            raise ValueError("spec_content argument must be supplied")

        try:
            spec_data = yaml.safe_load(spec_content)
        except yaml.YAMLError as e:
            raise IRValidatorException(f"There was a problem parsing the YAML content: {e}")

        required_fields = {'name', 'version', 'description'}  # Example required fields
        missing_fields = required_fields - set(spec_data.keys())

        if missing_fields:
            raise IRValidatorException(f"Missing required fields: {', '.join(missing_fields)}")

        return spec_data

def validate_from_file(yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """

    if yaml_file is None:
        raise ValueError("yaml_file argument must be supplied")

    try:
        with yaml_file.open() as f:
            data = yaml.safe_load(f)

        # Define required fields
        required_fields = {'field1', 'field2', 'field3'}

        # Check if all required fields are present
        for field in required_fields:
            if field not in data:
                raise IRValidatorException(f"Missing required field: {field}")

        return data

    except FileNotFoundError:
        raise IRValidatorException(f"File not found: {yaml_file}")

    except yaml.YAMLError as e:
        raise IRValidatorException(f"Error parsing YAML file: {e}")

    except Exception as e:
        raise IRValidatorException(f"An unexpected error occurred: {e}")

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """

    def resolve_includes(recursive=False, parsed=None):
        """Recursive helper function to resolve includes."""
        if parsed is None:
            parsed = {k: v for k, v in parser_dict.items() if k != 'includes'}
        if 'includes' in parser_dict:
            includes = parser_dict.pop('includes')
            for include in includes:
                include_path = include.get('module', include.get('file'))
                if not os.path.exists(include_path):
                    raise FileNotFoundError(f"Include file not found: {include_path}")
                with open(include_path, 'r') as file:
                    include_contents = file.read()
                include_dict = self._parse_spec(include_contents)
                if recursive:
                    include_dict = resolve_includes(recursive=True, parsed=include_dict)
                parsed.update(include_dict)
        return parsed

    return resolve_includes(recipe=True)

