    for arg in args:
        if not isinstance(arg, (int, float)):
            raise TypeError("All arguments must be numbers")

    for arg in args:
        if not hasattr(self, 'min_value') or not hasattr(self, 'max_value'):
            raise ValueError("Minimum and maximum values must be defined")

