    spec_path = os.path.join(plugin_dir, 'plugin.spec')
    if not os.path.isfile(spec_path):
        raise FileNotFoundError(f"The plugin spec file {spec_path} does not exist")

    with open(spec_path, 'r') as file:
        plugin_spec = json.load(file)

    flatten_dict = {}
    for key, value in plugin_spec.items():
        if isinstance(value, dict):
            flatten_dict.update({f"{key}.{k}": v for k, v in get_plugin_spec_flatten_dict(value).items()})
        else:
            flatten_dict[key] = value

    return flatten_dict

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    if "CONFIG_PATH" not in os.environ:
        os.environ["CONFIG_PATH"] = "/path/to/default/config"
